	async generateRoundRobinBracket(league, participants) {
		const matches = [];
		const now = (/* @__PURE__ */ new Date()).toISOString();
		const list = [...participants];
		if (list.length % 2 !== 0) list.push({
			id: "bye-player",
			leagueId: league.id,
			userToken: "bye-token",
			username: "BYE",
			joinedAt: now
		});
		const n = list.length;
		const rounds = n - 1;
		const half = n / 2;
		let globalMatchCount = 1;
		for (let round = 1; round <= rounds; round++) {
			for (let i = 0; i < half; i++) {
				const p1 = list[i];
				const p2 = list[n - 1 - i];
				if (p1.userToken === "bye-token" || p2.userToken === "bye-token") continue;
				const match = {
					id: `match-${league.id}-rr-r${round}-m${globalMatchCount}`,
					leagueId: league.id,
					round,
					matchNumber: globalMatchCount,
					bracketType: "round_robin",
					player1Token: p1.userToken,
					player1Name: p1.username,
					player1Score: 0,
					player2Token: p2.userToken,
					player2Name: p2.username,
					player2Score: 0,
					winnerToken: null,
					roomCode: null,
					status: "pending",
					createdAt: now
				};
				matches.push(match);
				globalMatchCount++;
			}
			list.splice(1, 0, list.pop());
		}
		league.status = "active";
		league.roundsCount = rounds;
		await dbRepository.saveLeague(league);
		await dbRepository.setLeagueMatches(matches);
		return matches;
	},
